load("data/wvs_postmat.rda")
wvs_ag <- wvs_postmat %>%
  group_by(B_COUNTRY_ALPHA) %>%
  summarise(
    postmat = mean(Y001, na.rm = TRUE),
    n = sum(!is.na(Y001)),
    s = sd(Y001, na.rm = TRUE),
    se = s / sqrt(n)
  ) %>%
  na.omit() %>%
  rename(country = B_COUNTRY_ALPHA) %>%
  arrange(postmat)

