set.seed(519)
sep_data <- tibble(grp = LETTERS[1:5], p = c(0, .25, .33, .5, .65))
sep_data <- sep_data %>%
  group_by(grp) %>%
  reframe(y = rbinom(25, 1, p))

g <- glm(y ~ grp, data = sep_data, family = binomial)
summary(g)


## -----------------------------------------------------------------------------
viztest(g, include_intercept = TRUE)


## -----------------------------------------------------------------------------
library(marginaleffects)
preds <- avg_predictions(g, variables = "grp", type = "link")
preds
viztest(preds, include_zero = FALSE)

